import re
from collections import deque

def solve(env, goal):
    # Parse goal: "look at <object-type> under the <lamp-type>" (wording may vary)
    goal_l = goal.lower()
    m = re.search(r'(?:look at|examine|inspect|see)\s+(?:the\s+|a\s+)?(\w+)', goal_l)
    obj_type = m.group(1) if m else None
    m = re.search(r'(?:under|with|by|using)\s+(?:the\s+|a\s+)?(\w+)', goal_l)
    lamp_type = m.group(1) if m else None
    # fallback: any known lamp-ish word
    if obj_type is None:
        m = re.search(r'\b(\w+)\b', goal_l)
        obj_type = m.group(1) if m else "book"
    if lamp_type is None:
        lamp_type = "desklamp"

    def parse_listing(text):
        # return list of (base, id, full) found in an observation
        items = []
        for m in re.finditer(r'([a-z]+)((?:\s+\d+)+)', text):
            base = m.group(1)
            ident = m.group(2).strip().split()[0]
            items.append((base, ident, base + " " + ident))
        return items

    def matches(items, base):
        return [full for (b, i, full) in items if b == base]

    def is_open(text, rec_full):
        # heuristic: after "open X" feedback doesn't say closed; we track state ourselves
        return rec_full in opened

    opened = set()
    inventory = []
    examined_targets = set()
    steps = 0

    def do(cmd):
        nonlocal steps
        steps += 1
        return env.step(cmd)

    def current_inv():
        # ask inventory; feedback like "You are carrying: a book 1."
        fb = env.step("inventory")
        inv = [full for (b, i, full) in parse_listing(fb)]
        return inv

    # parse room description for receptacles
    room_text = env.observation
    receptacles = []
    for (b, i, full) in parse_listing(room_text):
        if b in ("bed", "desk", "drawer", "cabinet", "shelf", "fridge", "microwave",
                 "safe", "garbagecan", "laundryhamper", "table", "sofa", "counter",
                 "sink", "box", "chest", "closet", "tabletop", "dresser"):
            receptacles.append(full)
    # also catch receptacles appearing as "a X N" in room text
    if not receptacles:
        for m in re.finditer(r'\b([a-z]+)\s+(\d+)', room_text):
            receptacles.append(m.group(1) + " " + m.group(2))

    # locations to search: room receptacles, then contents of openables
    search_locations = list(receptacles)
    visited = set()
    queue = deque(search_locations)
    # also handle: object may be inside closed receptacles; open them as we go

    found_obj = None
    found_lamp = None

    while queue:
        loc = queue.popleft()
        if loc in visited:
            continue
        visited.add(loc)
        fb = do("go to " + loc)
        # if location is closed, open it
        if fb.startswith("The") and "closed" in fb.lower():
            fb2 = do("open " + loc)
            opened.add(loc)
        # now observe
        fb = env.step("look")
        items = parse_listing(fb)
        # also items mentioned on loc itself
        for base, ident, full in items:
            if base == obj_type or obj_type in base:
                if found_obj is None:
                    found_obj = full
            if base == lamp_type or lamp_type in base:
                if found_lamp is None:
                    found_lamp = full
            # nested receptacles
            if base in ("drawer", "cabinet", "shelf", "fridge", "microwave", "safe",
                        "box", "chest", "closet", "dresser"):
                if full not in visited:
                    queue.append(full)
        if found_obj and found_lamp:
            break

    # If still not found, search by opening every receptacle more thoroughly
    if not found_obj:
        for loc in receptacles:
            try:
                do("go to " + loc)
                do("open " + loc)
            except Exception:
                pass
            fb = env.step("look")
            for base, ident, full in parse_listing(fb):
                if base == obj_type and not found_obj:
                    found_obj = full
                if base == lamp_type and not found_lamp:
                    found_lamp = full
    if not found_obj:
        # try inventory
        inv = current_inv()
        for full in inv:
            if obj_type in full:
                found_obj = full
    if not found_lamp:
        # last resort: use any lamp-like item seen
        for loc in receptacles:
            fb = env.step("go to " + loc)
            fb = env.step("look")
            for base, ident, full in parse_listing(fb):
                if "lamp" in base or "light" in base:
                    found_lamp = full
                    break
            if found_lamp:
                break

    if found_obj is None:
        return "Nothing happens."
    if found_lamp is None:
        found_lamp = lamp_type + " 1"

    # ensure we hold the object
    inv = current_inv()
    if found_obj not in inv:
        # go to its location and take it
        # need location: search locations for it
        loc_for_obj = None
        for loc in receptacles:
            fb = env.step("go to " + loc)
            fb = env.step("look")
            if found_obj in fb:
                loc_for_obj = loc
                break
            # maybe inside; open
            fb2 = env.step("open " + loc)
            fb3 = env.step("look")
            if found_obj in fb3:
                loc_for_obj = loc
                break
        if loc_for_obj is None:
            # try all
            for loc in receptacles:
                fb = env.step("go to " + loc)
                fb = env.step("open " + loc)
                fb = env.step("look")
                if found_obj in fb:
                    loc_for_obj = loc
                    break
        if loc_for_obj:
            do("go to " + loc_for_obj)
            do("take " + found_obj + " from " + loc_for_obj)
        else:
            # try taking from current
            do("take " + found_obj + " from " + receptacles[0])

    # turn on the lamp
    # go to lamp location
    for loc in receptacles:
        fb = env.step("go to " + loc)
        fb = env.step("look")
        if found_lamp in fb:
            do("go to " + loc)
            break
    fb = do("use " + found_lamp)
    # if lamp not found there, just use it
    if "cannot" in fb.lower() or "nothing" in fb.lower():
        do("use " + found_lamp)

    # examine while holding
    inv = current_inv()
    if found_obj not in inv:
        # try to take again from wherever
        for loc in receptacles:
            fb = env.step("go to " + loc)
            fb = env.step("open " + loc)
            fb = env.step("look")
            if found_obj in fb:
                do("go to " + loc)
                do("take " + found_obj + " from " + loc)
                break
    fb = do("examine " + found_obj)
    return fb
